using System;
using System.IO;
using System.Linq;
using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
namespace ParkingLotEnvironment.CloudPilot {
public static class CloudPilotMartCapture {
 const string W="Assets/ParkingLotEnvironment/CloudPilot/MartPilot";
 static Camera eye;static string output,path,hash;static int step=-2;static Vector3 pos;static Quaternion rot;static bool enabled;static float fov;static readonly StringBuilder log=new StringBuilder();
 static string Hash(string p){using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 public static void Capture(){try{var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"-parkingCaptureOutput");if(i<0)throw new Exception("Explicit output required");output=Path.GetFullPath(a[i+1]);Directory.CreateDirectory(output);i=Array.IndexOf(a,"-parkingMartScene");path=i>=0?a[i+1]:W+"/MartBakeWork.unity";hash=Hash(path);EditorSceneManager.OpenScene(path);var roots=SceneManager.GetActiveScene().GetRootGameObjects();var root=roots.Single(g=>g.name=="ParkingLot_CornerPilot_Root");if(roots.Single(g=>g.name=="ParkingLot_V35_Preserved").activeSelf||roots.Single(g=>g.name=="ParkingLot_Neighborhood_Preserved_20261103").activeSelf)throw new Exception("Preserved map active");eye=root.GetComponentInChildren<Camera>();pos=eye.transform.position;rot=eye.transform.rotation;fov=eye.fieldOfView;enabled=eye.enabled;eye.enabled=false;
  if(root.GetComponentsInChildren<Camera>().Length!=1)throw new Exception("Multiple active map cameras");if(root.transform.Find("ParkingSpaces_60_DesignDimensions").childCount!=60)throw new Exception("Bay count");if(root.GetComponentsInChildren<MeshRenderer>().Any(r=>r.sharedMaterials.Any(m=>m==null)))throw new Exception("Missing material");if(LightmapSettings.lightmaps.Length==0)throw new Exception("No baked lighting");
  foreach(var b in eye.GetComponents<MonoBehaviour>())if(b==null)throw new Exception("Missing camera script");
  log.AppendLine("ACTUAL UNITY SAVED SCENE. Layout prototype, not photographic benchmark approval. No global quality changes or hidden capture overrides.");log.AppendLine("Scene="+path+" SHA256="+hash+" Unity="+Application.unityVersion+" GPU="+SystemInfo.graphicsDeviceName);log.AppendLine("Quality="+QualitySettings.shadows+" AA="+QualitySettings.antiAliasing+" Color="+QualitySettings.activeColorSpace+" Lightmaps="+LightmapSettings.lightmaps.Length);log.AppendLine("Bays=60 activeVehicles="+root.GetComponentsInChildren<Transform>().Count(t=>t.name.StartsWith("Mart_Parked_")||t.name=="Mart_Loading_GenericBoxTruck")+" colliders="+root.GetComponentsInChildren<Collider>().Length);
  long tris=0;foreach(var m in root.GetComponentsInChildren<MeshFilter>())if(m.sharedMesh)tris+=m.sharedMesh.triangles.LongLength/3;log.AppendLine("ActiveMeshTrianglesIncludingLODs="+tris+" renderers="+root.GetComponentsInChildren<Renderer>().Length+"; no runtime FPS measurement.");foreach(var b in eye.GetComponents<MonoBehaviour>())log.AppendLine("SavedCameraEffect="+b.GetType().FullName+" enabled="+b.enabled);
  EditorApplication.update+=Tick;
 }catch(Exception e){Finish(e);}}
 static void Tick(){try{if(File.Exists("/workspaces/parkside-setup/STOP"))throw new Exception("STOP");if(step<0)Render(null,pos,rot,640,360,fov);else if(step==0)Render("mart-eye.png",pos,rot,1920,1080,fov);else if(step==1)Render("mart-aerial.png",new Vector3(56,61,-65),Quaternion.LookRotation(new Vector3(-56,-61,72)),1600,1000,56);else if(step==2)Render("mart-entrance.png",new Vector3(-16,1.65f,13.5f),Quaternion.LookRotation(new Vector3(18,.1f,14)),1280,720,65);else if(step==3)Render("mart-practice-aisle.png",new Vector3(-14,1.65f,-19),Quaternion.LookRotation(new Vector3(29,0,0)),1280,720,60);else if(step<6)Render("mart-move-"+(step-3)+".png",pos+Vector3.forward*(step-3)*3,rot,1280,720,fov);else{Finish(null);return;}step++;}catch(Exception e){Finish(e);}}
 static void Render(string n,Vector3 p,Quaternion r,int w,int h,float field){var rt=new RenderTexture(w,h,24,RenderTextureFormat.ARGB32){antiAliasing=1};var pix=new Texture2D(w,h,TextureFormat.RGB24,false);var prev=RenderTexture.active;var target=eye.targetTexture;try{rt.Create();eye.targetTexture=rt;eye.fieldOfView=field;eye.transform.SetPositionAndRotation(p,r);eye.Render();if(n!=null){RenderTexture.active=rt;pix.ReadPixels(new Rect(0,0,w,h),0,0);pix.Apply();File.WriteAllBytes(output+"/"+n,pix.EncodeToPNG());}}finally{eye.targetTexture=target;RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(pix);}}
 static void Finish(Exception e){EditorApplication.update-=Tick;if(eye){eye.transform.SetPositionAndRotation(pos,rot);eye.enabled=enabled;eye.fieldOfView=fov;}if(e==null&&Hash(path)!=hash)e=new Exception("Scene changed during capture");if(e!=null)Debug.LogException(e);log.AppendLine("Result="+(e==null?"CAPTURE_COMPLETE":e.ToString()));if(output!=null){File.WriteAllText(output+"/capture-report.txt",log.ToString());if(e==null)File.WriteAllText(output+"/capture-complete.txt",hash);}EditorApplication.Exit(e==null?0:1);}
}
}
